use snm03_combined_vulns::{handle_escalation, process_escalation, EscalationRequest};

// ---------------------------------------------------------------------------
// Happy path — must pass in both the vulnerable and secure versions.
// ---------------------------------------------------------------------------

#[test]
fn valid_request_succeeds() {
    let result = handle_escalation("ticket=1042;level=2;team=infra");
    assert!(result.is_ok(), "valid escalation request should succeed");
    assert_eq!(
        result.unwrap(),
        "Ticket 1042 escalated to level 2 -> routed to team infra"
    );
}

// ---------------------------------------------------------------------------
// Error-path tests — describe the behaviour expected from the secure version.
// Each test catches any panic so the test suite itself never crashes.
// ---------------------------------------------------------------------------

#[test]
fn missing_field_fails_safely_in_secure_version() {
    // "level" is absent — the vulnerable version panics on unwrap().
    let result = std::panic::catch_unwind(|| handle_escalation("ticket=1042;team=infra"));

    assert!(
        result.is_ok(),
        "secure version should not panic when a required field is missing"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should return an error for a missing required field"
    );
}

#[test]
fn non_numeric_level_fails_safely_in_secure_version() {
    // "level" is a word — the vulnerable version panics on parse().unwrap().
    let result =
        std::panic::catch_unwind(|| handle_escalation("ticket=1042;level=critical;team=infra"));

    assert!(
        result.is_ok(),
        "secure version should not panic when level is not a number"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should return an error for a non-numeric level"
    );
}

#[test]
fn malformed_segment_fails_safely_in_secure_version() {
    // A segment without '=' — the vulnerable version panics on split_once().unwrap().
    let result = std::panic::catch_unwind(|| handle_escalation("ticket=1042;BADFORMAT;team=infra"));

    assert!(
        result.is_ok(),
        "secure version should not panic on a malformed input segment"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should return an error for a malformed segment"
    );
}

#[test]
fn no_panic_on_empty_input_in_secure_version() {
    let result = std::panic::catch_unwind(|| handle_escalation(""));

    assert!(
        result.is_ok(),
        "secure version should not panic on empty input"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should return an error for empty input"
    );
}

#[test]
fn unknown_field_fails_safely_in_secure_version() {
    let result = std::panic::catch_unwind(|| {
        handle_escalation("ticket=1042;level=2;team=infra;region=eu-west")
    });

    assert!(
        result.is_ok(),
        "secure version should not panic when an unknown field is present"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should reject unknown fields instead of silently ignoring them"
    );
}

// ---------------------------------------------------------------------------
// Process step — out-of-range level is already handled without panicking in
// both versions, because process_escalation already returns Result.
// ---------------------------------------------------------------------------

#[test]
fn out_of_range_level_fails_safely() {
    let req = EscalationRequest {
        ticket_id: 999,
        level: 9,
        team: "ops".to_string(),
    };

    let result = process_escalation(&req);
    assert!(
        result.is_err(),
        "escalation level 9 is out of range and should be rejected"
    );
}

#[test]
fn level_zero_fails_safely() {
    let req = EscalationRequest {
        ticket_id: 1000,
        level: 0,
        team: "ops".to_string(),
    };

    let result = process_escalation(&req);
    assert!(
        result.is_err(),
        "escalation level 0 is out of range and should be rejected"
    );
}
